//! Generated WGSL for the BeliefState per-tick decay sweep.
//!
//! ## Why this lives in the compiler crate (not the runtime)
//!
//! The constraint that the runtime dispatch no hand-written WGSL
//! requires that any WGSL be either compiler-emitted from a `.sim`
//! source OR generated by a function in the compiler crate.
//!
//! Observe / scry / reveal are .sim-authored consumer rules
//! (see `assets/sim/tom_probe.sim` `ApplyObserveBeliefUpdate` /
//! `ApplyScryBeliefUpdate` / `ApplyRevealBeliefUpdate`). Decay is the
//! one verb that doesn't fit that shape today: it's a per-cell sweep
//! over the entire `agent_count^2` BeliefState SoA grid, and the DSL
//! has no `for_each_agent` body primitive that would let a per-agent
//! rule walk all cells. Adding such a primitive is future work;
//! meanwhile the WGSL must come from the compiler, not from a
//! `const &str` literal in the runtime crate.
//!
//! The shape mirrors the retired `DECAY_WGSL`:
//!
//!   * One thread per packed-byte word in the confidence column
//!     (`workgroup_size = 64`, dispatch `(cell_count + 3) / 4 / 64`
//!     workgroups).
//!   * Each thread reads its word, decrements every byte by 1
//!     saturating, with two skip rules:
//!     - cells observed THIS tick stay at 255 (no immediate undo of
//!       observe's writeback).
//!     - never-observed cells stay at 0 (the saturating arithmetic
//!       would no-op anyway; the guard is intent + perf hint).
//!
//! ## Pinned by `decay_pin.rs::decay_slope_is_one_per_tick`
//!
//! The companion regression pin asserts `confidence == 155` after
//! 100 ticks (= 255 - 100), so the implementation must produce a
//! linear slope. The simplest linear formulation is "decrement by 1
//! per call, skipping cells observed this tick".
//!
//! ## Why not `@decay(gate = BeliefStillFresh)` today
//!
//! The compiler supports per-cell `@decay(... gate = MaskName)` end-to-end:
//! the gate mask's predicate IR walk surfaces every storage handle it
//! touches, the decay kernel BGL extends with matching read bindings, and
//! the per-cell body inlines the predicate as `if (<pred>) { <decay step> }`.
//! See `cg/emit/kernel.rs::build_view_decay_wgsl` and the
//! `decay_mode_sub_and_gate.rs::gate_inlines_belief_state_predicate`
//! pin for the canonical example.
//!
//! Tom_probe's `confidence` column does NOT migrate to the auto-emitted
//! path because the storage is q8-packed (4 cells per u32 word,
//! decremented via byte-shift masks). The auto-emitted decay kernel
//! iterates per-CELL on `array<atomic<u32>>` with one logical cell per
//! u32; adopting it would require either a `@storage(packed_q8)`
//! annotation (no DSL surface today) or unpacking confidence to a flat
//! u32 column (4x storage + downstream readback / setter reformat).
//! Both are deferred; this hand-rolled per-word kernel stays in place until
//! one lands. See `assets/sim/tom_probe.sim`'s "Wave 3 ToM Phase 3.9"
//! header for the same gap chain documented at the .sim layer.

/// WGSL source for the per-tick BeliefState decay sweep kernel.
///
/// Returns a complete WGSL module the runtime feeds directly into
/// `wgpu::Device::create_shader_module`. Bind-group layout (slot
/// indices match the runtime's hand-built BGL):
///   * `@binding(0)` — `Cfg` uniform (carries `agent_count` +
///     `cell_count` + `tick`).
///   * `@binding(1)` — `beliefs_confidence` (read_write `array<u32>`
///     — host-side u8-per-cell, 4 packed LE bytes per word).
///   * `@binding(2)` — `beliefs_tick` (read `array<u32>` — last-seen
///     tick per cell).
///
/// Entry point: `cs_decay`.
pub fn decay_kernel_wgsl() -> String {
    r#"struct Cfg {
    observer: u32,
    target_or_subject: u32,
    subject: u32,
    agent_count: u32,
    tick: u32,
    cell_count: u32,
    _pad0: u32,
    _pad1: u32,
}

@group(0) @binding(0) var<uniform> cfg: Cfg;
@group(0) @binding(1) var<storage, read_write> beliefs_confidence: array<u32>;
@group(0) @binding(2) var<storage, read>       beliefs_tick:       array<u32>;

@compute @workgroup_size(64)
fn cs_decay(@builtin(global_invocation_id) gid: vec3<u32>) {
    let word_idx = gid.x;
    let cell_count = cfg.cell_count;
    let word_count = (cell_count + 3u) / 4u;
    if (word_idx >= word_count) { return; }

    let word = beliefs_confidence[word_idx];
    var new_word: u32 = 0u;

    for (var b: u32 = 0u; b < 4u; b = b + 1u) {
        let cell = word_idx * 4u + b;
        let shift = b * 8u;
        let conf = (word >> shift) & 0xFFu;
        var new_conf: u32 = conf;
        if (cell < cell_count) {
            let last = beliefs_tick[cell];
            let observed_this_tick = last == cfg.tick;
            let never_observed = last == 0u && conf == 0u;
            if (!observed_this_tick && !never_observed) {
                if (conf > 0u) {
                    new_conf = conf - 1u;
                } else {
                    new_conf = 0u;
                }
            }
        }
        new_word = new_word | ((new_conf & 0xFFu) << shift);
    }
    beliefs_confidence[word_idx] = new_word;
}
"#.to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decay_wgsl_has_entry_point_and_bindings() {
        let src = decay_kernel_wgsl();
        // Sanity checks: we expect a valid WGSL with cs_decay entry,
        // 3 bindings, and the cfg struct + storage qualifiers.
        assert!(src.contains("fn cs_decay"));
        assert!(src.contains("@group(0) @binding(0)"));
        assert!(src.contains("@group(0) @binding(1)"));
        assert!(src.contains("@group(0) @binding(2)"));
        assert!(src.contains("beliefs_confidence"));
        assert!(src.contains("beliefs_tick"));
    }
}
